    /// <summary>Font roles of the Cretacea UI (SDF assets generated by Assets/Editor/CretaceaFontAssets.cs).</summary>
    public enum UiFont
    {
        Heading,        // Barlow Condensed Bold — titles, headers, labels in caps
        Label,          // Barlow Condensed SemiBold — buttons, chips, small caps labels
        Body,           // Barlow Regular (real bold via <b>)
        BodyMedium,     // Barlow Medium — HUD body text over the world
        BodySemiBold,   // Barlow SemiBold
        Mono,           // Courier Prime — terminals, documents, timestamps
        MonoBold,
        Hand,           // Caveat — handwritten notes
        Stencil         // Stardos Stencil Bold — stencilled titles
    }

    /// <summary>
    /// Programmatic uGUI/TextMeshPro factory for Cretacea: Blackout: one warm survival-horror style for every screen.
    /// Warm near-black panels with 4 px rounded corners, a 1 px warm border and a soft shadow; warm off-white text
    /// with a soft black underlay; amber accent and focus, coral for danger, green only for the escape route.
    /// Sizes are in 1920x1080 reference pixels.
    /// </summary>
    public static class CretaceaUiFactory
    {
