        /// <summary>GLSL-style smoothstep (Mathf.SmoothStep interpolates between its first two arguments instead).</summary>
        public static float Smooth(float edge0, float edge1, float x)
        {
            float t = Mathf.Clamp01((x - edge0) / (edge1 - edge0));
            return t * t * (3f - 2f * t);
        }

        // ---- Canvas ---------------------------------------------------------------------------------------

        public static Canvas CreateRootCanvas(string name, int sortOrder)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(Canvas), typeof(CanvasScaler), typeof(GraphicRaycaster));
            Canvas canvas = go.GetComponent<Canvas>();
            canvas.renderMode = RenderMode.ScreenSpaceOverlay;
            canvas.sortingOrder = sortOrder;
            canvas.pixelPerfect = false;
            canvas.additionalShaderChannels |= AdditionalCanvasShaderChannels.TexCoord1 | AdditionalCanvasShaderChannels.Normal | AdditionalCanvasShaderChannels.Tangent;

            CanvasScaler scaler = go.GetComponent<CanvasScaler>();
            scaler.uiScaleMode = CanvasScaler.ScaleMode.ScaleWithScreenSize;
            scaler.referenceResolution = new Vector2(1920f, 1080f);
            scaler.screenMatchMode = CanvasScaler.ScreenMatchMode.MatchWidthOrHeight;
            scaler.matchWidthOrHeight = 0.5f;

            EnsureEventSystem();
            return canvas;
        }

        public static void EnsureEventSystem()
        {
            if (UnityEngine.Object.FindAnyObjectByType<EventSystem>() != null) return;
            var esGo = new GameObject("[EventSystem]", typeof(EventSystem), typeof(InputSystemUIInputModule));
            UnityEngine.Object.DontDestroyOnLoad(esGo);
        }

        /// <summary>Gives keyboard / gamepad focus to a control (shows the amber focus outline).</summary>
        public static void Focus(Selectable target)
        {
            if (target == null || EventSystem.current == null) return;
            EventSystem.current.SetSelectedGameObject(null);
            EventSystem.current.SetSelectedGameObject(target.gameObject);
        }

        // ---- Fonts ----------------------------------------------------------------------------------------

        private static string FontAssetName(UiFont role)
        {
            switch (role)
            {
                case UiFont.Heading: return "BarlowCondensed-Bold SDF";
                case UiFont.Label: return "BarlowCondensed-SemiBold SDF";
                case UiFont.Body: return "Barlow-Regular SDF";
                case UiFont.BodyMedium: return "Barlow-Medium SDF";
                case UiFont.BodySemiBold: return "Barlow-SemiBold SDF";
                case UiFont.Mono: return "CourierPrime-Regular SDF";
                case UiFont.MonoBold: return "CourierPrime-Bold SDF";
                case UiFont.Hand: return "Caveat-Regular SDF";
                case UiFont.Stencil: return "StardosStencil-Bold SDF";
            }
            return "Barlow-Regular SDF";
        }

        public static TMP_FontAsset ResolveFont(UiFont role)
        {
            if (s_Fonts.TryGetValue(role, out TMP_FontAsset cached) && cached != null) return cached;
            TMP_FontAsset fa = Resources.Load<TMP_FontAsset>("UI/Fonts/" + FontAssetName(role));
            if (fa == null)
            {
                fa = role == UiFont.Mono || role == UiFont.MonoBold ? ResolveMonoFont()
                    : role == UiFont.Heading || role == UiFont.Label || role == UiFont.Stencil ? ResolveHeaderFont()
                    : ResolveBodyFont();
            }
            s_Fonts[role] = fa;
            return fa;
        }

        public static TMP_FontAsset ResolveHeaderFont(TMP_FontAsset preferred = null)
        {
            if (preferred != null) return preferred;
            return Resources.Load<TMP_FontAsset>("UI/Fonts/BarlowCondensed-Bold SDF") ?? FallbackFont();
        }

        public static TMP_FontAsset ResolveBodyFont(TMP_FontAsset preferred = null)
        {
            if (preferred != null) return preferred;
            return Resources.Load<TMP_FontAsset>("UI/Fonts/Barlow-Regular SDF") ?? ResolveHeaderFont();
        }

        public static TMP_FontAsset ResolveMonoFont(TMP_FontAsset preferred = null)
        {
            if (preferred != null) return preferred;
            return Resources.Load<TMP_FontAsset>("UI/Fonts/CourierPrime-Regular SDF") ?? ResolveBodyFont();
        }

        private static TMP_FontAsset FallbackFont()
        {
            return Resources.Load<TMP_FontAsset>("Fonts & Materials/LiberationSans SDF")
                   ?? (TMP_Settings.instance != null ? TMP_Settings.defaultFontAsset : null);
        }

        /// <summary>The font's "Shadow" preset (soft black underlay) so text holds over bright lamps.</summary>
        public static Material ShadowMaterial(TMP_FontAsset font)
        {
            if (font == null) return null;
            if (s_ShadowMats.TryGetValue(font, out Material m) && m != null) return m;
            m = Resources.Load<Material>("UI/Fonts/" + font.name + " Shadow");
            s_ShadowMats[font] = m;
            return m;
        }

        /// <summary>Switches a text to another font role, keeping the shadow preset.</summary>
        public static void SetFont(TMP_Text tmp, UiFont role, bool shadow = true)
        {
            if (tmp == null) return;
            TMP_FontAsset fa = ResolveFont(role);
            tmp.font = fa;
            Material sm = shadow ? ShadowMaterial(fa) : null;
            tmp.fontSharedMaterial = sm != null ? sm : fa.material;
            tmp.fontStyle = FontStyles.Normal;
            tmp.characterSpacing = role == UiFont.Heading || role == UiFont.Label ? 1.5f : 0f;
        }

