        public static RectTransform CreatePanel(
            Transform parent,
            string name,
            Color color,
            Vector2 anchorMin,
            Vector2 anchorMax,
            Vector2 offsetMin,
            Vector2 offsetMax,
            bool raycastTarget = false)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(CretaceaPanelGraphic));
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.anchorMin = anchorMin;
            rt.anchorMax = anchorMax;
            rt.offsetMin = offsetMin;
            rt.offsetMax = offsetMax;

            CretaceaPanelGraphic img = go.GetComponent<CretaceaPanelGraphic>();
            img.color = color;
            img.raycastTarget = raycastTarget;
            return rt;
        }

        public static RectTransform CreateAnchoredPanel(
            Transform parent,
            string name,
            Color color,
            Vector2 anchor,
            Vector2 pivot,
            Vector2 anchoredPosition,
            Vector2 size,
            bool raycastTarget = false)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(CretaceaPanelGraphic));
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.anchorMin = anchor;
            rt.anchorMax = anchor;
            rt.pivot = pivot;
            rt.anchoredPosition = anchoredPosition;
            rt.sizeDelta = size;

            CretaceaPanelGraphic img = go.GetComponent<CretaceaPanelGraphic>();
