        /// <summary>Rounded card: 1 px warm border and a soft drop shadow.</summary>
        public static RectTransform StyleCard(RectTransform rt, float radius = 4f, float shadow = 0.55f, Color? border = null)
        {
            CretaceaPanelGraphic g = rt != null ? rt.GetComponent<CretaceaPanelGraphic>() : null;
            if (g != null) g.SetStyle(UiPanelStyle.Card, radius, border ?? BorderSubtle, 1f, shadow);
            return rt;
        }

        /// <summary>Rounded corners only (bars, tracks, fills, pills).</summary>
        public static RectTransform StyleRounded(RectTransform rt, float radius = 4f)
        {
            CretaceaPanelGraphic g = rt != null ? rt.GetComponent<CretaceaPanelGraphic>() : null;
            if (g != null) g.SetStyle(UiPanelStyle.Rounded, radius, Color.clear, 1f, 0f);
            return rt;
        }

        // ---- Text -----------------------------------------------------------------------------------------

        public static TextMeshProUGUI CreateText(
            Transform parent,
            string name,
            string text,
            float fontSize,
            Color color,
            TextAlignmentOptions alignment = TextAlignmentOptions.Left,
            bool isHeader = false,
            bool isMono = false)
        {
            UiFont role = isMono ? UiFont.Mono : (isHeader ? UiFont.Heading : UiFont.Body);
            return CreateText(parent, name, text, fontSize, color, role, alignment);
        }

        public static TextMeshProUGUI CreateText(
            Transform parent,
            string name,
            string text,
            float fontSize,
            Color color,
            UiFont role,
            TextAlignmentOptions alignment = TextAlignmentOptions.Left,
            bool shadow = true)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(TextMeshProUGUI));
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.anchorMin = Vector2.zero;
            rt.anchorMax = Vector2.one;
            rt.offsetMin = Vector2.zero;
            rt.offsetMax = Vector2.zero;

            TextMeshProUGUI tmp = go.GetComponent<TextMeshProUGUI>();
            SetFont(tmp, role, shadow);
            TMP_SpriteAsset keys = KeySpriteAsset();
            if (keys != null) tmp.spriteAsset = keys;   // inline keycaps from FormatKeyTokens
            tmp.text = text;
            tmp.fontSize = fontSize;
            tmp.color = color;
            tmp.alignment = alignment;
            tmp.textWrappingMode = TextWrappingModes.Normal;
            tmp.overflowMode = TextOverflowModes.Overflow;
            tmp.raycastTarget = false;
            if (role == UiFont.Body || role == UiFont.BodyMedium || role == UiFont.BodySemiBold)
            {
                tmp.lineSpacing = 4f;
            }
            return tmp;
        }

        private static readonly Regex s_KeyToken = new Regex(@"\[([A-Za-z0-9 /]{1,16})\]");

        /// <summary>
        /// "[E]" style key tokens in running text become the same keycap art the prompt uses (inline TMP sprites
        /// from Resources/UI/Keys/key_atlas). "[Hold Space]" reads "HOLD [space]", "[LB / L3]" shows both keys.
        /// Tokens with no keycap fall back to amber bold "[KEY]" text.
        /// </summary>
        public static string FormatKeyTokens(string s)
        {
            if (string.IsNullOrEmpty(s)) return string.Empty;
            bool haveSprites = KeySpriteAsset() != null;
            return s_KeyToken.Replace(s, m =>
            {
                string token = m.Groups[1].Value.Trim();
                if (haveSprites)
                {
                    string inline = KeyTokenToSprites(token);
                    if (inline != null) return inline;
                }
                return $"<color={AmberHex}><b>[{token.ToUpperInvariant()}]</b></color>";
            });
        }

        private static string KeyTokenToSprites(string token)
        {
            string t = token.ToUpperInvariant();
            string prefix = string.Empty;
            if (t.StartsWith("HOLD ")) { prefix = $"<color={MutedHex}>HOLD</color> "; t = t.Substring(5).Trim(); }
            string[] parts = t.Split('/');
            var sb = new System.Text.StringBuilder(prefix);
            for (int i = 0; i < parts.Length; i++)
            {
                string atlasName = KeyAtlasName(parts[i].Trim());
                if (atlasName == null) return null;
                if (i > 0) sb.Append($"<color={MutedHex}>/</color>");
                sb.Append("<sprite name=\"").Append(atlasName).Append("\">");
            }
            return sb.ToString();
        }

        /// <summary>Atlas sprite name for a key label ("TAB", "ESC", gamepad "X" ...), or null if there is no art.</summary>
        public static string KeyAtlasName(string key)
        {
            if (string.IsNullOrEmpty(key)) return null;
            string k = key.Trim().ToUpperInvariant();
            switch (k)
            {
                case "ESCAPE": k = "ESC"; break;
                case "RETURN": k = "ENTER"; break;
                case "SPACEBAR": k = "SPACE"; break;
            }
            string name;
            switch (k)
            {
                case "A": case "B": case "X": case "Y": name = "pad_" + k.ToLowerInvariant(); break;   // gamepad face buttons
                default: name = k.ToLowerInvariant(); break;
            }
            EnsureKeyAtlas();
            return s_KeyRects != null && s_KeyRects.ContainsKey(name) ? name : null;
        }

        // ---- Key atlas (Resources/UI/Keys/key_atlas.png + .json, made by docs/handin/ui_tools/make_key_atlas.py) ----

        [Serializable] private class KeyAtlasEntry { public string name; public int x, y, w, h; }
        [Serializable] private class KeyAtlasData { public int height; public KeyAtlasEntry[] keys; }

        private static Texture2D s_KeyAtlas;
        private static Dictionary<string, Rect> s_KeyRects;
        private static bool s_KeyAtlasTried;
        private static TMP_SpriteAsset s_KeySpriteAsset;
        private static readonly Dictionary<string, Sprite> s_AtlasSprites = new Dictionary<string, Sprite>();

        private static void EnsureKeyAtlas()
        {
            if (s_KeyAtlasTried) return;
            s_KeyAtlasTried = true;
            s_KeyAtlas = Resources.Load<Texture2D>("UI/Keys/key_atlas");
            TextAsset json = Resources.Load<TextAsset>("UI/Keys/key_atlas");
            if (s_KeyAtlas == null || json == null) { s_KeyAtlas = null; return; }
            KeyAtlasData data = JsonUtility.FromJson<KeyAtlasData>(json.text);
            if (data == null || data.keys == null) { s_KeyAtlas = null; return; }
            s_KeyRects = new Dictionary<string, Rect>();
            foreach (KeyAtlasEntry e in data.keys) s_KeyRects[e.name] = new Rect(e.x, e.y, e.w, e.h);
        }

        /// <summary>Keycap sprite cut from the key atlas (same art as the inline text keys).</summary>
        public static Sprite AtlasKeySprite(string atlasName)
        {
            EnsureKeyAtlas();
            if (s_KeyAtlas == null || atlasName == null || !s_KeyRects.TryGetValue(atlasName, out Rect r)) return null;
            if (s_AtlasSprites.TryGetValue(atlasName, out Sprite cached) && cached != null) return cached;
            Sprite spr = Sprite.Create(s_KeyAtlas, r, new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
            spr.name = "key_" + atlasName;
            s_AtlasSprites[atlasName] = spr;
            return spr;
        }

        /// <summary>
        /// Runtime TMP sprite asset over the key atlas, so running text can show &lt;sprite name="tab"&gt;. Keys are
        /// ~1.5 em tall, centred on the cap height, with a small gap either side.
        /// </summary>
        public static TMP_SpriteAsset KeySpriteAsset()
        {
            if (s_KeySpriteAsset != null) return s_KeySpriteAsset;
            EnsureKeyAtlas();
            if (s_KeyAtlas == null) return null;
            // The material asset in Resources keeps the TMP sprite shader in player builds.
            Material matAsset = Resources.Load<Material>("UI/Keys/key_atlas_mat");
            Shader sh = matAsset != null ? matAsset.shader : Shader.Find("TextMeshPro/Sprite");
            if (sh == null) return null;

            TMP_SpriteAsset sa = ScriptableObject.CreateInstance<TMP_SpriteAsset>();
            sa.name = "CretaceaKeys";
            sa.hideFlags = HideFlags.DontSave;
            // Mark as current-format so TMP does not try to "upgrade" (and wipe) the tables built here.
            System.Reflection.FieldInfo ver = typeof(TMP_Asset).GetField("m_Version", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
            if (ver != null) ver.SetValue(sa, "1.1.0");
            sa.spriteInfoList = new List<TMP_Sprite>();
            sa.spriteSheet = s_KeyAtlas;
            var mat = matAsset != null ? new Material(matAsset) : new Material(sh);
            mat.name = "CretaceaKeys Material";
            mat.hideFlags = HideFlags.DontSave;
            mat.SetTexture(ShaderUtilities.ID_MainTex, s_KeyAtlas);
            sa.material = mat;

            uint index = 0;
            foreach (KeyValuePair<string, Rect> kv in s_KeyRects)
            {
                Rect r = kv.Value;
                const float keyH = 64f;
                // bearingY: key centred on the cap height (spans ~-0.4 .. +1.1 em)
                var metrics = new UnityEngine.TextCore.GlyphMetrics(r.width, r.height, 3f, keyH * 0.74f, r.width + 6f);
                var rect = new UnityEngine.TextCore.GlyphRect((int)r.x, (int)r.y, (int)r.width, (int)r.height);
                var glyph = new TMP_SpriteGlyph(index, metrics, rect, 1.5f, 0);
                sa.spriteGlyphTable.Add(glyph);
                var ch = new TMP_SpriteCharacter(0xFFFE, sa, glyph) { name = kv.Key, scale = 1f };
                sa.spriteCharacterTable.Add(ch);
                index++;
            }
            sa.UpdateLookupTables();
            s_KeySpriteAsset = sa;
            return sa;
        }

        /// <summary>Splits off the first "[KEY]" token: returns the key ("E", "HOLD X", "TAB") and the rest of the text.</summary>
        public static string ExtractKey(string s, out string rest)
        {
            rest = s ?? string.Empty;
            if (string.IsNullOrEmpty(s)) return null;
            Match m = s_KeyToken.Match(s);
            if (!m.Success) return null;
            rest = (s.Substring(0, m.Index) + s.Substring(m.Index + m.Length)).Replace("  ", " ").Trim();
            return m.Groups[1].Value.Trim().ToUpperInvariant();
        }

        // ---- Keycap ---------------------------------------------------------------------------------------

        public sealed class Keycap
        {
            public RectTransform Root;
            public Image Art;
            public CretaceaPanelGraphic Cap;
            public TextMeshProUGUI Label;

            public void SetKey(string key)
            {
                key = string.IsNullOrEmpty(key) ? "E" : key.ToUpperInvariant();
                Sprite art = KeySprite(key);
                float h = Root.sizeDelta.y;
                if (art != null)
                {
                    Art.sprite = art;
                    Art.enabled = true;
                    Cap.enabled = false;
                    Label.text = string.Empty;
                    Root.sizeDelta = new Vector2(h * art.rect.width / Mathf.Max(1f, art.rect.height), h);
                }
                else
                {
                    Art.enabled = false;
                    Cap.enabled = true;
                    Label.text = key;
                    float w = Mathf.Max(h, Label.GetPreferredValues(key).x + 22f);
                    Root.sizeDelta = new Vector2(w, h);
                }
            }
        }

        private static readonly Dictionary<string, Sprite> s_KeySprites = new Dictionary<string, Sprite>();

        /// <summary>Keycap art for a key: the key atlas (project art for E/F/C/Shift, matching caps for the rest),
        /// else the project's single key textures in Resources/UI/HUD.</summary>
        public static Sprite KeySprite(string key)
        {
            Sprite fromAtlas = AtlasKeySprite(KeyAtlasName(key));
            if (fromAtlas != null) return fromAtlas;
            string file = key switch { "E" => "key_e", "F" => "key_f", "C" => "key_c", "SHIFT" => "key_shift", _ => null };
            if (file == null) return null;
            if (s_KeySprites.TryGetValue(file, out Sprite s) && s != null) return s;
            s = LoadSprite("UI/HUD/" + file);
            s_KeySprites[file] = s;
            return s;
        }

        public static Keycap CreateKeycap(Transform parent, string name, float height)
        {
            var go = new GameObject(name, typeof(RectTransform));
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.sizeDelta = new Vector2(height, height);

            var k = new Keycap { Root = rt };
            RectTransform cap = CreatePanel(rt, "Cap", new Color(0.23f, 0.235f, 0.25f, 1f), Vector2.zero, Vector2.one, new Vector2(0f, 0f), Vector2.zero);
            StyleCard(cap, 6f, 0.6f, new Color(0.55f, 0.56f, 0.58f, 0.85f));
            k.Cap = cap.GetComponent<CretaceaPanelGraphic>();
            k.Cap.shadowSpread = 6f;
            k.Cap.shadowOffset = new Vector2(0f, -3f);
            k.Label = CreateText(cap, "Key", "E", height * 0.6f, Color.white, UiFont.Heading, TextAlignmentOptions.Center, shadow: false);   // glyph >= 60% of the chip
            k.Label.characterSpacing = 1f;
            k.Label.rectTransform.offsetMin = new Vector2(6f, 3f);
            k.Label.rectTransform.offsetMax = new Vector2(-6f, 0f);
            k.Label.textWrappingMode = TextWrappingModes.NoWrap;

            var artGo = new GameObject("Art", typeof(RectTransform), typeof(Image));
            RectTransform art = artGo.GetComponent<RectTransform>();
            art.SetParent(rt, false);
            art.anchorMin = Vector2.zero; art.anchorMax = Vector2.one; art.offsetMin = Vector2.zero; art.offsetMax = Vector2.zero;
            k.Art = artGo.GetComponent<Image>();
            k.Art.raycastTarget = false;
            k.Art.preserveAspect = true;
            k.Art.enabled = false;
            return k;
        }

        // ---- Buttons --------------------------------------------------------------------------------------

        public static Button CreateButton(
            Transform parent,
            string name,
            string label,
            Vector2 size,
            Action onClick,
            float fontSize = 24f,
            bool accent = false)
        {
            var go = new GameObject(name, typeof(RectTransform), typeof(CretaceaPanelGraphic), typeof(Button), typeof(LayoutElement));
            RectTransform rt = go.GetComponent<RectTransform>();
            rt.SetParent(parent, false);
            rt.sizeDelta = size;

            LayoutElement le = go.GetComponent<LayoutElement>();
            le.preferredWidth = size.x;
            le.preferredHeight = size.y;

            CretaceaPanelGraphic bg = go.GetComponent<CretaceaPanelGraphic>();
            // Accent buttons rest dark with an amber outline; only the focused / hovered control gets the warm fill,
            // so one element on a screen looks lit.
            Color baseCol = ButtonNormal;
            bg.color = baseCol;
            Color border = accent ? new Color(AccentAmber.r, AccentAmber.g, AccentAmber.b, 0.85f) : BorderSubtle;
            bg.SetStyle(UiPanelStyle.Card, 4f, border, 1f, 0.35f);
            bg.shadowSpread = 8f;

            Button btn = go.GetComponent<Button>();
            btn.transition = Selectable.Transition.None;
            btn.targetGraphic = bg;

            TextMeshProUGUI txt = CreateText(rt, "Label", label, Mathf.Max(20f, fontSize), TextPrimary, UiFont.Label, TextAlignmentOptions.MidlineLeft);
            txt.rectTransform.offsetMin = new Vector2(22f, 2f);
            txt.rectTransform.offsetMax = new Vector2(-16f, -2f);
            txt.textWrappingMode = TextWrappingModes.NoWrap;
            txt.overflowMode = TextOverflowModes.Ellipsis;

            CretaceaButtonFx fx = go.AddComponent<CretaceaButtonFx>();
            fx.panel = bg;
            fx.label = txt;
            fx.baseColor = baseCol;
            fx.hoverColor = accent ? new Color(0.43f, 0.267f, 0.082f, 0.97f) : ButtonHover;
            fx.pressedColor = ButtonPressed;
            fx.baseBorder = border;
            fx.labelColor = accent ? new Color(1f, 0.86f, 0.62f, 1f) : TextPrimary;

            if (onClick != null)
            {
                btn.onClick.AddListener(() =>
                {
                    Cretacea.Core.GameEvents.RaisePlaySound("ui_click");
                    onClick.Invoke();
                });
            }

            return btn;
        }

        /// <summary>Main-menu list row: bare text that gains a warm plate, amber border and amber bar when hot.</summary>
        public static Button CreateListButton(Transform parent, string name, string label, Vector2 size, Action onClick, float fontSize = 30f)
        {
            Button btn = CreateButton(parent, name, label, size, onClick, fontSize);
            CretaceaButtonFx fx = btn.GetComponent<CretaceaButtonFx>();
            fx.listStyle = true;
            fx.hoverColor = new Color(0.20f, 0.13f, 0.06f, 0.70f);
            fx.labelColor = new Color(0.86f, 0.83f, 0.76f, 1f);
            fx.labelHotColor = new Color(1f, 0.86f, 0.62f, 1f);
            CretaceaPanelGraphic bg = btn.GetComponent<CretaceaPanelGraphic>();
            bg.shadowAlpha = 0f;
            TextMeshProUGUI txt = fx.label;
            SetFont(txt, UiFont.Heading);
            txt.fontSize = fontSize;
            txt.characterSpacing = 3f;
            txt.rectTransform.offsetMin = new Vector2(30f, 2f);
            RectTransform bar = CreatePanel(btn.transform, "AccentBar", AccentAmber, new Vector2(0f, 0.22f), new Vector2(0f, 0.78f), new Vector2(10f, 0f), new Vector2(14f, 0f));
            StyleRounded(bar, 2f);
            fx.accentBar = bar.GetComponent<Image>();
            fx.SetBaseColor(new Color(0f, 0f, 0f, 0f));
            return btn;
        }

        /// <summary>
        /// Resting look of a factory button that marks a current choice (active tab, selected row): dark fill, amber
        /// outline and amber label. Hover / focus still adds the warm fill on top, so focus stays distinguishable.
        /// </summary>
        public static void SetButtonChosen(Button btn, bool chosen)
        {
            if (btn == null) return;
            CretaceaButtonFx fx = btn.GetComponent<CretaceaButtonFx>();
            if (fx == null) return;
            fx.baseBorder = chosen ? new Color(AccentAmber.r, AccentAmber.g, AccentAmber.b, 0.9f) : BorderSubtle;
            fx.labelColor = chosen ? new Color(1f, 0.86f, 0.62f, 1f) : TextMuted;
            fx.SetBaseColor(chosen ? new Color(0.133f, 0.11f, 0.086f, 0.96f) : ButtonNormal);
        }

        /// <summary>Changes a factory button's resting fill (e.g. the active journal tab) without fighting its hover effect.</summary>
        public static void SetButtonBaseColor(Button btn, Color c)
        {
            if (btn == null) return;
            CretaceaButtonFx fx = btn.GetComponent<CretaceaButtonFx>();
            if (fx != null) fx.SetBaseColor(c);
            else if (btn.targetGraphic != null) btn.targetGraphic.color = c;
        }

        // ---- Slider / toggle rows -------------------------------------------------------------------------

        /// <summary>
        /// Bipolar slider (for example brightness -5..+5): the amber fill runs from a centre tick to the knob instead
        /// of from the left end, so 0 reads as "neutral", not "half".
        /// </summary>
        public static void MakeSliderBipolar(Slider slider)
        {
            if (slider == null || slider.fillRect == null) return;
            RectTransform fill = slider.fillRect;
            slider.fillRect = null;
            RectTransform tick = CreatePanel(slider.transform, "CentreTick", new Color(0.93f, 0.90f, 0.84f, 0.55f),
                new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(-1f, -9f), new Vector2(1f, 9f));
            Transform handleArea = slider.handleRect != null ? slider.handleRect.parent : null;
            if (handleArea != null) tick.SetSiblingIndex(handleArea.GetSiblingIndex());
            void Sync(float v)
            {
                float n = Mathf.InverseLerp(slider.minValue, slider.maxValue, v);
                fill.anchorMin = new Vector2(Mathf.Min(0.5f, n), 0f);
                fill.anchorMax = new Vector2(Mathf.Max(0.5f, n), 1f);
                fill.offsetMin = Vector2.zero;
                fill.offsetMax = Vector2.zero;
            }
            slider.onValueChanged.AddListener(Sync);
            Sync(slider.value);
        }

        public static Slider CreateSliderRow(
            Transform parent,
            string label,
            float min,
            float max,
            float initialValue,
            Action<float> onValueChanged,
            Func<float, string> valueFormatter = null)
        {
            var row = new GameObject($"Row_{label}", typeof(RectTransform), typeof(LayoutElement));
            RectTransform rowRt = row.GetComponent<RectTransform>();
            rowRt.SetParent(parent, false);
            LayoutElement le = row.GetComponent<LayoutElement>();
            le.preferredHeight = 52f;
            le.flexibleWidth = 1f;

            RectTransform hot = CreatePanel(rowRt, "RowFocus", new Color(1f, 0.85f, 0.6f, 0f), Vector2.zero, Vector2.one, new Vector2(-12f, 0f), new Vector2(12f, 0f));
            StyleCard(hot, 4f, 0f, new Color(0f, 0f, 0f, 0f));

            TextMeshProUGUI nameTmp = CreateText(rowRt, "Name", label, 22f, TextPrimary, UiFont.BodyMedium, TextAlignmentOptions.MidlineLeft);
            nameTmp.rectTransform.anchorMin = new Vector2(0f, 0f);
            nameTmp.rectTransform.anchorMax = new Vector2(0.42f, 1f);
            nameTmp.textWrappingMode = TextWrappingModes.NoWrap;

            TextMeshProUGUI valTmp = CreateText(rowRt, "Value", FormatValue(initialValue, valueFormatter), 22f, AccentAmber, UiFont.Label, TextAlignmentOptions.MidlineRight);
            valTmp.rectTransform.anchorMin = new Vector2(0.84f, 0f);
            valTmp.rectTransform.anchorMax = new Vector2(1f, 1f);
            valTmp.textWrappingMode = TextWrappingModes.NoWrap;

            var sliderGo = new GameObject("Slider", typeof(RectTransform), typeof(Slider));
            RectTransform sliderRt = sliderGo.GetComponent<RectTransform>();
            sliderRt.SetParent(rowRt, false);
            sliderRt.anchorMin = new Vector2(0.44f, 0.5f);
            sliderRt.anchorMax = new Vector2(0.82f, 0.5f);
            sliderRt.offsetMin = new Vector2(0f, -14f);
            sliderRt.offsetMax = new Vector2(0f, 14f);

            // Raycast target so a click / hover on the track reaches the slider (not only on the knob).
            RectTransform track = CreatePanel(sliderRt, "Track", TrackColor,
                new Vector2(0f, 0.5f), new Vector2(1f, 0.5f), new Vector2(0f, -3f), new Vector2(0f, 3f), raycastTarget: true);
            StyleRounded(track, 3f);

            // Fill ends at the knob centre: same 10 px insets as the handle area.
            RectTransform fillArea = CreatePanel(sliderRt, "FillArea", Color.clear,
                new Vector2(0f, 0.5f), new Vector2(1f, 0.5f), new Vector2(10f, -3f), new Vector2(-10f, 3f));
            RectTransform fill = CreatePanel(fillArea, "Fill", AccentAmber,
                Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            StyleRounded(fill, 3f);

            var handleArea = new GameObject("HandleArea", typeof(RectTransform));
            RectTransform haRt = handleArea.GetComponent<RectTransform>();
            haRt.SetParent(sliderRt, false);
            // A 0 px tall handle area on the track's centre line: Slider stretches the handle over the area's
            // height, so a full-height area would turn the 20x20 knob into a 20x48 capsule.
            haRt.anchorMin = new Vector2(0f, 0.5f);
            haRt.anchorMax = new Vector2(1f, 0.5f);
            haRt.offsetMin = new Vector2(10f, 0f);
            haRt.offsetMax = new Vector2(-10f, 0f);

            RectTransform handle = CreateAnchoredPanel(haRt, "Handle", TextPrimary,
                new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(20f, 20f), raycastTarget: true);
            StyleCard(handle, 10f, 0.5f, new Color(0f, 0f, 0f, 0.35f));
            CretaceaPanelGraphic handleG = handle.GetComponent<CretaceaPanelGraphic>();
            handleG.shadowSpread = 6f;
            handleG.shadowOffset = new Vector2(0f, -2f);

            Slider slider = sliderGo.GetComponent<Slider>();
            slider.minValue = min;
            slider.maxValue = max;
            slider.value = Mathf.Clamp(initialValue, min, max);
            slider.fillRect = fill;
            slider.handleRect = handle;
            slider.targetGraphic = handleG;
            slider.transition = Selectable.Transition.None;

            RowFocusFx rowFx = sliderGo.AddComponent<RowFocusFx>();
            rowFx.plate = hot.GetComponent<CretaceaPanelGraphic>();
            rowFx.handle = handleG;
            rowFx.label = nameTmp;

            slider.onValueChanged.AddListener(v =>
            {
                valTmp.text = FormatValue(v, valueFormatter);
                onValueChanged?.Invoke(v);
            });

            return slider;
        }

        public static Toggle CreateToggleRow(
            Transform parent,
            string label,
            bool initialValue,
            Action<bool> onValueChanged)
        {
            var row = new GameObject($"Toggle_{label}", typeof(RectTransform), typeof(LayoutElement));
            RectTransform rowRt = row.GetComponent<RectTransform>();
            rowRt.SetParent(parent, false);
            LayoutElement le = row.GetComponent<LayoutElement>();
            le.preferredHeight = 52f;
            le.flexibleWidth = 1f;

            RectTransform hot = CreatePanel(rowRt, "RowFocus", new Color(1f, 0.85f, 0.6f, 0f), Vector2.zero, Vector2.one, new Vector2(-12f, 0f), new Vector2(12f, 0f));
            StyleCard(hot, 4f, 0f, new Color(0f, 0f, 0f, 0f));

            TextMeshProUGUI nameTmp = CreateText(rowRt, "Name", label, 22f, TextPrimary, UiFont.BodyMedium, TextAlignmentOptions.MidlineLeft);
            nameTmp.rectTransform.anchorMin = new Vector2(0f, 0f);
            nameTmp.rectTransform.anchorMax = new Vector2(0.70f, 1f);

            TextMeshProUGUI stateTxt = CreateText(rowRt, "StateText", initialValue ? "ON" : "OFF", 20f, initialValue ? AccentAmber : TextMuted, UiFont.Label, TextAlignmentOptions.MidlineRight);
            stateTxt.rectTransform.anchorMin = new Vector2(0.70f, 0f);
            stateTxt.rectTransform.anchorMax = new Vector2(1f, 1f);
            stateTxt.rectTransform.offsetMax = new Vector2(-80f, 0f);

            var toggleGo = new GameObject("Toggle", typeof(RectTransform), typeof(Toggle));
            RectTransform toggleRt = toggleGo.GetComponent<RectTransform>();
            toggleRt.SetParent(rowRt, false);
            toggleRt.anchorMin = new Vector2(1f, 0.5f);
            toggleRt.anchorMax = new Vector2(1f, 0.5f);
            toggleRt.pivot = new Vector2(1f, 0.5f);
            toggleRt.sizeDelta = new Vector2(60f, 30f);

            RectTransform bg = CreatePanel(toggleRt, "Bg", TrackColor,
                Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero, raycastTarget: true);
            StyleCard(bg, 15f, 0f, new Color(BorderSubtle.r, BorderSubtle.g, BorderSubtle.b, 0.45f));
            RectTransform check = CreatePanel(bg, "Check", AccentAmber,
                Vector2.zero, Vector2.one, Vector2.zero, Vector2.zero);
            StyleRounded(check, 15f);
            RectTransform knob = CreateAnchoredPanel(bg, "Knob", TextPrimary,
                new Vector2(0f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(15f, 0f), new Vector2(22f, 22f));
            StyleCard(knob, 11f, 0.45f, new Color(0f, 0f, 0f, 0.3f));
            knob.GetComponent<CretaceaPanelGraphic>().shadowSpread = 5f;

            Toggle toggle = toggleGo.GetComponent<Toggle>();
            toggle.targetGraphic = bg.GetComponent<Image>();
            toggle.graphic = check.GetComponent<Image>();
            toggle.transition = Selectable.Transition.None;
            toggle.toggleTransition = Toggle.ToggleTransition.None;
            toggle.isOn = initialValue;

            RowFocusFx rowFx = toggleGo.AddComponent<RowFocusFx>();
            rowFx.plate = hot.GetComponent<CretaceaPanelGraphic>();
            rowFx.handle = bg.GetComponent<CretaceaPanelGraphic>();
            rowFx.label = nameTmp;

            void Refresh(bool v)
            {
                stateTxt.text = v ? "ON" : "OFF";
                stateTxt.color = v ? AccentAmber : TextMuted;
                knob.anchorMin = knob.anchorMax = new Vector2(v ? 1f : 0f, 0.5f);
                knob.anchoredPosition = new Vector2(v ? -15f : 15f, 0f);
                knob.GetComponent<Image>().color = v ? new Color(0.12f, 0.08f, 0.03f, 1f) : TextMuted;
            }

            toggle.onValueChanged.AddListener(v =>
            {
                Refresh(v);
                Cretacea.Core.GameEvents.RaisePlaySound("ui_click");
                onValueChanged?.Invoke(v);
            });
            Refresh(initialValue);
            return toggle;
        }

        private static string FormatValue(float v, Func<float, string> fmt)
        {
            return fmt != null ? fmt(v) : $"{Mathf.RoundToInt(v * 100f)}%";
        }

        // =========================================================================
        // SPRITES (project art first, procedural fallback)
        // =========================================================================

        /// <summary>Loads a sprite from Resources whether the texture imported as a single or a multiple sprite.</summary>
        public static Sprite LoadSprite(string resourcePath)
        {
            Sprite s = Resources.Load<Sprite>(resourcePath);
            if (s != null) return s;
            Sprite[] all = Resources.LoadAll<Sprite>(resourcePath);
            return all != null && all.Length > 0 ? all[0] : null;
        }

        public static Sprite GetWhiteSprite()
        {
            if (_cachedWhiteSprite != null) return _cachedWhiteSprite;
            var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false) { name = "UI_White" };
            tex.SetPixels(new[] { Color.white, Color.white, Color.white, Color.white });
            tex.Apply();
            _cachedWhiteSprite = Sprite.Create(tex, new Rect(0, 0, 2, 2), new Vector2(0.5f, 0.5f));
            return _cachedWhiteSprite;
        }

        public static Sprite GetCircleSprite()
        {
            if (_cachedCircleSprite != null) return _cachedCircleSprite;
            const int size = 128;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, true) { name = "UI_Circle", wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Trilinear };
            float half = size * 0.5f;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float d = Vector2.Distance(new Vector2(x + 0.5f, y + 0.5f), new Vector2(half, half));
                    float a = Mathf.Clamp01(half - 1.5f - d + 0.5f);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
                }
            }
            tex.Apply(true);
            _cachedCircleSprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));
            return _cachedCircleSprite;
        }

        private static Sprite _cachedGlowSprite;

        /// <summary>Soft radial glow: alpha 1 at the centre falling smoothly to 0 at the rim (a lamp's halo).</summary>
        public static Sprite GetGlowSprite()
        {
            if (_cachedGlowSprite != null) return _cachedGlowSprite;
            const int size = 64;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, true) { name = "UI_Glow", wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Trilinear };
            float half = size * 0.5f;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float d = Vector2.Distance(new Vector2(x + 0.5f, y + 0.5f), new Vector2(half, half)) / half;
                    float a = Mathf.Clamp01(1f - d);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a * a * (3f - 2f * a)));
                }
            }
            tex.Apply(true);
            _cachedGlowSprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));
            return _cachedGlowSprite;
        }

        // ---- Park-security kit dressing (round 4 art direction) ---------------------------------------------------
        // Review 3: pause, settings, controls and the tablet were the same flat near-black cards, closer to a modern app
        // than a 1996 park-security kit. DressKitCard gives a card the kit's hardware, restrained so legibility is
        // untouched: a faint worn-paint grain, a pressed-steel bevel (a light line under the top edge, a dark one over the
        // bottom), four slotted screw heads in the corners and, optionally, the park badge. Call it right after the card
        // is created: its pieces are the card's first children, so every label and button draws over them.
        public static void DressKitCard(RectTransform card, bool badge, Vector2 badgeAnchor, Vector2 badgePosition, float badgeSize = 64f)
        {
            if (card == null) return;

            var wearGo = new GameObject("KitWear", typeof(RectTransform), typeof(RawImage));
            RectTransform wear = wearGo.GetComponent<RectTransform>();
            wear.SetParent(card, false);
            wear.anchorMin = Vector2.zero; wear.anchorMax = Vector2.one;
            wear.offsetMin = new Vector2(5f, 5f); wear.offsetMax = new Vector2(-5f, -5f);
            RawImage wi = wearGo.GetComponent<RawImage>();
            wi.texture = GetWearTexture();
            wi.color = new Color(1f, 0.94f, 0.82f, 0.005f);   // 0.010 lifted every card from 13 to ~20 and flattened the bands (round 4 critic)   // the UI blends in linear: 0.01 is a few sRGB levels on the card
            wi.raycastTarget = false;
            Vector2 sz = card.rect.size.sqrMagnitude > 1f ? card.rect.size : card.sizeDelta;
            wi.uvRect = new Rect(0f, 0f, Mathf.Max(1f, sz.x / 256f), Mathf.Max(1f, sz.y / 256f));   // 1:1 texels at the 1080 reference

            CreatePanel(card, "KitBevelTop", new Color(1f, 0.95f, 0.85f, 0.022f), new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(8f, -3f), new Vector2(-8f, -2f));
            CreatePanel(card, "KitBevelBottom", new Color(0f, 0f, 0f, 0.55f), new Vector2(0f, 0f), new Vector2(1f, 0f), new Vector2(8f, 2f), new Vector2(-8f, 3f));

            Vector2[] corners = { new Vector2(0f, 1f), new Vector2(1f, 1f), new Vector2(0f, 0f), new Vector2(1f, 0f) };
            float[] slotAngles = { 28f, -52f, 74f, 12f };   // screws are never all turned the same way
            for (int i = 0; i < corners.Length; i++)
            {
                Vector2 c = corners[i];
                Vector2 pos = new Vector2(c.x < 0.5f ? 15f : -15f, c.y < 0.5f ? 15f : -15f);
                RectTransform head = CreateAnchoredPanel(card, $"KitScrew{i}", new Color(0.235f, 0.222f, 0.200f, 1f), c, new Vector2(0.5f, 0.5f), pos, new Vector2(11f, 11f));
                Image hi = head.GetComponent<Image>();
                hi.sprite = GetCircleSprite();
                RectTransform rim = CreateAnchoredPanel(head, "Rim", new Color(0f, 0f, 0f, 0.55f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(0.4f, -0.6f), new Vector2(13f, 13f));
                rim.GetComponent<Image>().sprite = GetCircleSprite();
                rim.SetAsFirstSibling();
                RectTransform shine = CreateAnchoredPanel(head, "Shine", new Color(1f, 0.96f, 0.88f, 0.16f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), new Vector2(-1.6f, 1.6f), new Vector2(5f, 5f));
                shine.GetComponent<Image>().sprite = GetCircleSprite();
                RectTransform slot = CreateAnchoredPanel(head, "Slot", new Color(0.04f, 0.035f, 0.03f, 0.95f), new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f), Vector2.zero, new Vector2(8f, 1.8f));
                slot.localRotation = Quaternion.Euler(0f, 0f, slotAngles[i]);
            }

            if (badge) AddParkBadge(card, badgeAnchor, badgePosition, badgeSize);
        }

        /// <summary>The park badge (UI/Brand/park_logo), pivoted on its anchor corner.</summary>
        public static RectTransform AddParkBadge(RectTransform parent, Vector2 anchor, Vector2 position, float size)
        {
            Texture2D logoTex = Resources.Load<Texture2D>("UI/Brand/park_logo");
            if (logoTex == null || parent == null) return null;
            var logoGo = new GameObject("KitBadge", typeof(RectTransform), typeof(RawImage));
            RectTransform lrt = logoGo.GetComponent<RectTransform>();
            lrt.SetParent(parent, false);
            lrt.anchorMin = lrt.anchorMax = anchor;
            lrt.pivot = anchor;
            lrt.anchoredPosition = position;
            lrt.sizeDelta = new Vector2(size, size);
            RawImage logo = logoGo.GetComponent<RawImage>();
            logo.texture = logoTex;
            logo.color = new Color(1f, 1f, 1f, 0.92f);
            logo.raycastTarget = false;
            return lrt;
        }

        private static Texture2D _cachedWearTexture;

        /// <summary>Tileable worn-paint grain: soft blotches, fine speckle and a few long scratches (white, alpha only).</summary>
        public static Texture2D GetWearTexture()
        {
            if (_cachedWearTexture != null) return _cachedWearTexture;
            const int size = 256;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "UI_KitWear", wrapMode = TextureWrapMode.Repeat, filterMode = FilterMode.Bilinear };
            var px = new Color32[size * size];
            var rng = new System.Random(1996);
            var lattice = new float[size * size];
            for (int i = 0; i < lattice.Length; i++) lattice[i] = (float)rng.NextDouble();
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    // tileable blotches: two octaves of wrapped value noise (cells of 32 and 16 px), no visible lattice
                    float blot = 0.65f * WrappedValueNoise(x, y, 32, size, lattice) + 0.35f * WrappedValueNoise(x, y, 16, size, lattice);
                    float speck = (float)rng.NextDouble();
                    float a = Mathf.Clamp01(Mathf.Pow(blot, 2.2f) * 0.4f + (speck > 0.99f ? 0.7f : speck * 0.18f));
                    px[y * size + x] = new Color32(255, 255, 255, (byte)(a * 255f));
                }
            }
            // a few long, thin scratches
            for (int s = 0; s < 9; s++)
            {
                float x0 = (float)rng.NextDouble() * size, y0 = (float)rng.NextDouble() * size;
                float ang = (float)(rng.NextDouble() * Math.PI);
                int len = 30 + rng.Next(90);
                for (int t = 0; t < len; t++)
                {
                    int sx = ((int)(x0 + Mathf.Cos(ang) * t) % size + size) % size;
                    int sy = ((int)(y0 + Mathf.Sin(ang) * t) % size + size) % size;
                    px[sy * size + sx] = new Color32(255, 255, 255, 255);
                }
            }
            tex.SetPixels32(px);
            tex.Apply(false, true);
            _cachedWearTexture = tex;
            return tex;
        }

        private static float WrappedValueNoise(int x, int y, int cell, int size, float[] lattice)
        {
            int n = size / cell;
            float fx = x / (float)cell, fy = y / (float)cell;
            int x0 = Mathf.FloorToInt(fx), y0 = Mathf.FloorToInt(fy);
            float tx = fx - x0, ty = fy - y0;
            tx = tx * tx * (3f - 2f * tx); ty = ty * ty * (3f - 2f * ty);
            float L(int i, int j) => lattice[((j % n + n) % n) * size + ((i % n + n) % n)];
            float a = Mathf.Lerp(L(x0, y0), L(x0 + 1, y0), tx);
            float b = Mathf.Lerp(L(x0, y0 + 1), L(x0 + 1, y0 + 1), tx);
            return Mathf.Lerp(a, b, ty);
        }

        public static Sprite GetRadialRingSprite()
        {
            if (_cachedRingSprite != null) return _cachedRingSprite;
            const int size = 128;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, true) { name = "UI_RadialRing", wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Trilinear };
            float half = size * 0.5f;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float r = Vector2.Distance(new Vector2(x + 0.5f, y + 0.5f), new Vector2(half, half));
                    float outer = Mathf.Clamp01(half - 2f - r + 0.5f);
                    float inner = Mathf.Clamp01(r - (half - 12f) + 0.5f);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, outer * inner));
                }
            }
            tex.Apply(true);
            _cachedRingSprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));
            return _cachedRingSprite;
        }

        public static Sprite GetVignetteSprite()
        {
            if (_cachedVignetteSprite != null) return _cachedVignetteSprite;
            Sprite fromRes = LoadSprite("UI/HUD/damage_red") ?? LoadSprite("UI/HUD/vignette");
            if (fromRes != null) { _cachedVignetteSprite = fromRes; return _cachedVignetteSprite; }

            const int size = 256;
            var tex = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "UI_Vignette", wrapMode = TextureWrapMode.Clamp };
            float half = (size - 1) * 0.5f;
            for (int y = 0; y < size; y++)
            {
                for (int x = 0; x < size; x++)
                {
                    float nx = (x - half) / half;
                    float ny = (y - half) / half;
                    float radial = Mathf.Clamp01(Mathf.Sqrt(nx * nx + ny * ny) / 1.25f);
                    float a = Mathf.Pow(Smooth(0.35f, 1.0f, radial), 1.6f);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
                }
            }
            tex.Apply();
            _cachedVignetteSprite = Sprite.Create(tex, new Rect(0, 0, size, size), new Vector2(0.5f, 0.5f));
            return _cachedVignetteSprite;
        }

        /// <summary>Horizontal gradient, opaque on the left fading to clear on the right (menu sidebar, banners).</summary>
        public static Sprite GetSideGradientSprite()
        {
            if (_cachedSideGradient != null) return _cachedSideGradient;
            const int w = 256, h = 4;
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, false) { name = "UI_SideGradient", wrapMode = TextureWrapMode.Clamp };
            for (int x = 0; x < w; x++)
            {
                float t = x / (float)(w - 1);
                float a = t < 0.30f ? 1f : Mathf.Pow(1f - Smooth(0.30f, 1f, t), 1.6f);
                for (int y = 0; y < h; y++) tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
            }
            tex.Apply();
            _cachedSideGradient = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));
            return _cachedSideGradient;
        }

        /// <summary>Soft elliptical plate (chapter title card, death screen): dense in the middle, no visible edge.</summary>
        public static Sprite GetSoftPlateSprite()
        {
            if (_cachedSoftPlate != null) return _cachedSoftPlate;
            const int w = 256, h = 128;
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, false) { name = "UI_SoftPlate", wrapMode = TextureWrapMode.Clamp };
            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    float nx = (x + 0.5f) / w * 2f - 1f;
                    float ny = (y + 0.5f) / h * 2f - 1f;
                    float d = Mathf.Sqrt(nx * nx * 0.85f + ny * ny);
                    float a = Mathf.Pow(Mathf.Clamp01(1f - d), 1.3f);
                    a = a * a * (3f - 2f * a);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
                }
            }
            tex.Apply();
            _cachedSoftPlate = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));
            return _cachedSoftPlate;
        }

        public static Sprite GetStealthEyeSprite(int opennessLevel) // 0=Closed, 1=Half, 2=Open
        {
            if (opennessLevel <= 0 && _cachedEyeClosedSprite != null) return _cachedEyeClosedSprite;
            if (opennessLevel == 1 && _cachedEyeHalfSprite != null) return _cachedEyeHalfSprite;
            if (opennessLevel >= 2 && _cachedEyeOpenSprite != null) return _cachedEyeOpenSprite;

            const int w = 160;
            const int h = 80;
            var tex = new Texture2D(w, h, TextureFormat.RGBA32, true) { name = $"UI_StealthEye_{opennessLevel}", wrapMode = TextureWrapMode.Clamp, filterMode = FilterMode.Trilinear };
            float cx = w * 0.5f;
            float cy = h * 0.5f;
            float lidHeight = opennessLevel <= 0 ? 0.06f : (opennessLevel == 1 ? 0.40f : 0.80f);
            float aa = 1.5f / (cy * 0.9f);

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    float nx = (x + 0.5f - cx) / (cx * 0.92f);
                    float ny = (y + 0.5f - cy) / (cy * 0.90f);
                    float a = 0f;
                    if (Mathf.Abs(nx) <= 1.02f)
                    {
                        float arch = Mathf.Max(0f, 1f - nx * nx) * lidHeight;
                        float distRim = Mathf.Abs(Mathf.Abs(ny) - arch);
                        a = Mathf.Max(a, Mathf.Clamp01((0.11f - distRim) / aa));
                        if (opennessLevel >= 1 && Mathf.Abs(ny) < arch)
                        {
                            float pupilDist = Mathf.Sqrt(nx * nx * 2.4f + ny * ny * 1.2f);
                            float iris = Mathf.Clamp01((0.44f - pupilDist) / aa);
                            float pupil = Mathf.Clamp01((0.16f - pupilDist) / aa);
                            a = Mathf.Max(a, iris * (1f - pupil * 0.75f));
                        }
                    }
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
                }
            }
            tex.Apply(true);
            Sprite spr = Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f));

            if (opennessLevel <= 0) _cachedEyeClosedSprite = spr;
            else if (opennessLevel == 1) _cachedEyeHalfSprite = spr;
            else _cachedEyeOpenSprite = spr;
            return spr;
        }
    }
}
